const input = $input.first().json.body || $input.first().json;

const name = input.name || input.candidateName || 'Unknown';
const email = input.email || '';
const phone = input.phone || '';
const resumeText = input.resumeText || input.resume || '';
const position = input.position || input.role || 'General';
const experience = input.yearsExperience || input.experience || 0;

return {
  json: {
    name,
    email,
    phone,
    resumeText,
    position,
    experience,
    appliedAt: new Date().toISOString()
  }
};

