const response = $input.first().json;
const candidateData = $('Normalize Candidate Data').first().json;

let screening;
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  const cleanContent = content.replace(/```json|```/g, '').trim();
  screening = JSON.parse(cleanContent);
} catch (e) {
  screening = {
    fitScore: 0,
    experienceSummary: 'Unable to analyze',
    keySkills: '',
    strengths: '',
    concerns: 'Manual review required',
    cultureFit: 'Unknown',
    recommendedAction: 'HOLD'
  };
}

return {
  json: {
    ...candidateData,
    ...screening
  }
};
